export function getDefaultSlotContent(host): string {
  let htmlContent = host.innerHTML?.trim();
  let start: number, end: number;
  if (isIconSlotProvided(host)) {
    start = htmlContent.indexOf(host.querySelector('[slot="start"]').outerHTML);
    end = host.querySelector('[slot="start"]').outerHTML.length;
    if (start === 0) {
      htmlContent = htmlContent.substring(end);
    } else {
      htmlContent = htmlContent.substring(0, start);
    }
  }
  if (isDescriptionSlotProvided(host)) {
    start = htmlContent.indexOf(host.querySelector('[slot="description"]').outerHTML);
    end = host.querySelector('[slot="description"]').outerHTML.length;
    if (start === 0) {
      htmlContent = htmlContent.substring(end);
    } else {
      htmlContent = htmlContent.substring(0, start);
    }
  }
  return htmlContent.trim();
}

export function isIconSlotProvided(host): boolean {
  return !!host.querySelector('[slot="start"]');
}

export function isDescriptionSlotProvided(host): boolean {
  return !!host.querySelector('[slot="description"]');
}
